const form = $("On form submission").first().json;
const ai = $input.first().json;

// แปลงข้อมูลจาก AI
function parseAI(value) {
  if (value && typeof value === "object" && !Array.isArray(value)) {
    return value;
  }

  if (typeof value !== "string" || !value.trim()) {
    return {};
  }

  let text = value.trim()
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

  try {
    return JSON.parse(text);
  } catch (e) {
    // ลองค้นหา JSON ที่อยู่ภายในข้อความ
    const start = text.indexOf("{");
    const end = text.lastIndexOf("}");

    if (start !== -1 && end > start) {
      try {
        return JSON.parse(text.slice(start, end + 1));
      } catch (e2) {
        // ข้อความไม่ใช่ JSON ที่สมบูรณ์
      }
    }

    return { "ข้อความจาก AI": text };
  }
}

// รองรับผลลัพธ์จาก AI Agent หลายรูปแบบ
let raw = ai.output ?? ai.text ?? ai.response ?? ai;
let data = parseAI(raw);

if (typeof data.output === "string") {
  data = parseAI(data.output);
} else if (
  data.output &&
  typeof data.output === "object"
) {
  data = data.output;
}

function pick(...values) {
  for (const value of values) {
    if (value !== undefined && value !== null &&
        String(value).trim() !== "") {
      return value;
    }
  }
  return "";
}

const ข้อความAI = pick(
  data["ข้อความจาก AI"],
  data["output"],
  data["text"],
  typeof raw === "string" ? raw : ""
);

const อาการเสีย = pick(
  form["อาการ/ปัญหาที่พบ"],
  form["อาการเสีย"],
  data["อาการเสีย"]
);

const สาเหตุ = pick(
  data["สาเหตุ"],
  data["สาเหตุที่คาดว่าเกิดขึ้น"],
  data["สาเหตุที่เป็นไปได้"]
);

const ความเร่งด่วน = pick(
  data["ความเร่งด่วน"],
  data["ระดับความเร่งด่วน"],
  data["urgency"],
  data["priority"],
  ai["ความเร่งด่วน"],
  ai["ระดับความเร่งด่วน"]
);

const รายละเอียด = pick(
  data["รายละเอียด"],
  data["แนวทางแก้ไขเบื้องต้น"],
  data["แนวทางแก้ไข"],
  data["วิธีแก้ไข"],
  data["ข้อเสนอแนะ"],
  data["คำแนะนำ"],
  data["รายละเอียดการแก้ไข"],
  ai["รายละเอียด"],
  ai["แนวทางแก้ไขเบื้องต้น"]
);

return [{
  json: {
    "ชื่อผู้แจ้ง": form["ชื่อผู้แจ้ง"] ?? "",
    "อีเมล": form["อีเมล"] ?? "",
    "อุปกรณ์": pick(
      form["ประเภทอุปกรณ์"],
      form["อุปกรณ์"]
    ),
    "หมายเลขเครื่อง": pick(
      form["หมายเลขอุปกรณ์"],
      form["หมายเลขเครื่อง"]
    ),
    "สถานที่": pick(
      form["ห้องเรียน"],
      form["สถานที่"]
    ),
    "อาการเสีย": อาการเสีย,
    "สาเหตุ": สาเหตุ,
    "ความเร่งด่วน": ความเร่งด่วน,
    "รายละเอียด": รายละเอียด,
    "ข้อความจาก AI": ข้อความAI,
    "สถานะ": "รอซ่อม"
  }
}];

const rows = $input.all().map(item => item.json);

function getField(row, keywords) {
  for (const [key, value] of Object.entries(row)) {
    const normalizedKey = key.trim().toLowerCase();

    if (
      keywords.some(keyword =>
        normalizedKey === keyword.toLowerCase()
      ) &&
      value !== null &&
      value !== undefined &&
      String(value).trim() !== ""
    ) {
      return String(value).trim();
    }
  }

  return "";
}

const normalizedRows = rows.map(row => {
  const detail = getField(row, [
    "รายละเอียด",
    "แนวทางแก้ไขเบื้องต้น"
  ]);

  const statusMatch = detail.match(
    /สถานะ\s*[:：]\s*([^\n,]+)/i
  );

  const equipment = getField(row, [
    "อุปกรณ์",
    "ประเภทอุปกรณ์",
    "ชื่ออุปกรณ์"
  ]);

  const urgency = getField(row, [
    "ความเร่งด่วน",
    "ระดับความเร่งด่วน"
  ]);

  const status = getField(row, [
    "สถานะ",
    "สถานะการซ่อม",
    "สถานะงาน"
  ]) || statusMatch?.[1]?.trim() || "";

  return {
    "สถานะ": status || "ไม่ระบุ",
    "ประเภทอุปกรณ์": equipment || "ไม่ระบุ",
    "ความเร่งด่วน": urgency || "ไม่ระบุ"
  };
});

function countBy(field) {
  const counts = {};

  for (const row of normalizedRows) {
    const value = row[field];
    counts[value] = (counts[value] || 0) + 1;
  }

  return Object.entries(counts)
    .map(([name, count]) => `- ${name}: ${count} รายการ`)
    .join("\n") || "- ไม่มีข้อมูล";
}

const completed = ["ซ่อมเสร็จแล้ว", "เสร็จสิ้น", "ปิดงาน"];
const pendingStatuses = ["รอซ่อม", "กำลังซ่อม", "รอดำเนินการ"];

const done = normalizedRows.filter(row =>
  completed.includes(row["สถานะ"])
).length;

const pending = normalizedRows.filter(row =>
  pendingStatuses.includes(row["สถานะ"])
).length;

const unknown = normalizedRows.filter(row =>
  row["สถานะ"] === "ไม่ระบุ"
).length;

return [{
  json: {
    "วันที่รายงาน": new Date().toLocaleDateString("th-TH", {
      timeZone: "Asia/Bangkok",
      day: "2-digit",
      month: "2-digit",
      year: "numeric"
    }),
    "จำนวนรายการแจ้งซ่อมทั้งหมด": rows.length,
    "จำนวนงานค้าง": pending,
    "จำนวนงานซ่อมเสร็จแล้ว": done,
    "จำนวนรายการที่ไม่ทราบสถานะ": unknown,
    "สรุปตามสถานะ": countBy("สถานะ"),
    "สรุปตามประเภทอุปกรณ์": countBy("ประเภทอุปกรณ์"),
    "สรุปตามความเร่งด่วน": countBy("ความเร่งด่วน")
  }
}];
